cd /tmp/work && cat > cmp.py <<'EOF'
import fitz,sys
a=fitz.open('/app/input/agreement.pdf'); b=fitz.open('out/agreement.pdf')
def lines(p):
    r=[]
    for bl in p.get_text('dict')['blocks']:
        for l in bl.get('lines',[]):
            t=''.join(s['text'] for s in l['spans']).strip()
            if t: r.append((round(l['spans'][0]['origin'][1],1),round(l['bbox'][0]),t[:40]))
    return r
for i in map(int,sys.argv[1:]):
    la,lb=lines(a[i-1]),lines(b[i-1])
    db={t:(y,x) for y,x,t in lb}
    for y,x,t in la:
        if t in db: print(f'{y:7} {db[t][0]:7} d={db[t][0]-y:6.1f} x{x}/{db[t][1]} {t}')
        else: print(f'{y:7}   ---  {t}')
EOF
